SELECT user_id, arrayMap(e -> e.3, arraySort(groupArray((occurred_at, event_id, path)))) AS paths, arrayMap(d -> toInt32(d), arrayDifference(arrayMap(e -> e.1, arraySort(groupArray((occurred_at, event_id, path)))))) AS gapsSeconds, arrayMap(e -> e.3, groupArraySorted(3)((occurred_at, event_id, path))) AS firstThree, count() AS events FROM events WHERE user_id IN (112, 113, 245) AND occurred_at BETWEEN '2026-10-29 00:00:00' AND '2026-10-29 23:59:59' GROUP BY user_id ORDER BY user_id ASC
